def find_id(sorted_ids, target):
    low, high = 0, len(sorted_ids) - 1
    while low <= high:
        middle = (low + high) // 2
        if sorted_ids[middle] == target:
            return middle
        if sorted_ids[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1

