import { useState } from "react";

function Planner() {
  const [planned, setPlanned] = useState([]);

  function addCourse(code) {
    if (!planned.includes(code)) {
      setPlanned([...planned, code]);
    }
  }

  return (
    <div>
      <CourseList onAdd={addCourse} />
      <PlanSummary planned={planned} />
    </div>
  );
}

